.help-text {
  font-size: 0.875rem;
  color: var(--text-help);
  margin-top: 0.35rem;
  margin-bottom: 1rem;
}

/* ── Options list ── */
.options {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  margin-top: 1rem;
