.option label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--bg-option);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.7rem 0.9rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  user-select: none;
  min-height: 44px;
