.field-error {
  display: none;
  font-size: 0.85rem;
  color: var(--error);
  margin-top: 0.6rem;
  gap: 0.35rem;
  align-items: center;
}

.field-error.visible {
  display: flex;
}

fieldset[aria-invalid="true"] {
  border-left: 3px solid var(--error);
  padding-left: calc(1.5rem - 3px);
}

