AssistantMessageToolRequest(name='create', tool_call_id='tooluse_mXot17DFPXyG6PLlwoGwTq', arguments={'file_text': '/**
 * Quiz data – each question lists all correct answer values.
 * A question is "correct" when the user's selection exactly matches
 * the set of correct answers (no more, no less).
 */
const QUESTIONS = [
  {
    id: "q1",
    correctAnswers: new Set(["typescript", "java", "rust"]),
  },
  {
    id: "q2",
    correctAnswers: new Set(["c", "rust", "go"]),
  },
  {
    id: "q3",
    correctAnswers: new Set(["javascript", "python", "haskell"]),
  },
];

const form = document.getElementById("quiz-form");
const resultsEl = document.getElementById("results");
const scoreDisplay = document.getElementById("score-display");
const resultsMessage = document.getElementById("results-message");
const retryBtn = document.getElementById("retry-btn");
const liveRegion = document.getElementById("live-region");

const MESSAGES = [
  { threshold: 3, text: "Perfect score! You really know your languages. 🏆" },
  { threshold: 2, text: "Great job! Almost there. 🎯" },
  { threshold: 1, text: "Not bad — keep studying and try again! 📚" },
  { threshold: 0, text: "Don't give up — every expert started somewhere. 💡" },
];

form.addEventListener("submit", (e) => {
  e.preventDefault();

  let allValid = true;
  let firstInvalidFieldset = null;

  // Validate: at least one option selected per question
  QUESTIONS.forEach(({ id }) => {
    const fieldset = document.getElementById(`fieldset-${id}`);
    const errorEl = document.getElementById(`error-${id}`);
    const checked = fieldset.querySelectorAll('input[type="checkbox"]:checked');

    if (checked.length === 0) {
      fieldset.setAttribute("aria-invalid", "true");
      fieldset.setAttribute("aria-describedby", `error-${id}`);
      errorEl.classList.add("visible");
      allValid = false;
      if (!firstInvalidFieldset) firstInvalidFieldset = fieldset;
    } else {
      clearError(fieldset, errorEl);
    }
  });

  if (!allValid) {
    firstInvalidFieldset.querySelector('input[type="checkbox"]').focus();
    liveRegion.textContent =
      "Please answer all questions before submitting.";
    return;
  }

  // Score
  let score = 0;
  QUESTIONS.forEach(({ id, correctAnswers }) => {
    const fieldset = document.getElementById(`fieldset-${id}`);
    const checked = fieldset.querySelectorAll('input[type="checkbox"]:checked');
    const selected = new Set([...checked].map((cb) => cb.value));

    const isCorrect =
      selected.size === correctAnswers.size &&
      [...selected].every((v) => correctAnswers.has(v));

    if (isCorrect) score++;
  });

  // Show results
  scoreDisplay.textContent = `${score} / ${QUESTIONS.length}`;
  resultsMessage.textContent =
    MESSAGES.find((m) => score >= m.threshold)?.text ?? "";

  form.hidden = true;
  resultsEl.classList.add("visible");
  resultsEl.removeAttribute("hidden");

  liveRegion.textContent = `Quiz complete. You scored ${score} out of ${QUESTIONS.length}.`;
  document.getElementById("results-heading").focus();
});

retryBtn.addEventListener("click", () => {
  // Reset form
  form.reset();
  QUESTIONS.forEach(({ id }) => {
    const fieldset = document.getElementById(`fieldset-${id}`);
    const errorEl = document.getElementById(`error-${id}`);
    clearError(fieldset, errorEl);
  });

  resultsEl.classList.remove("visible");
  resultsEl.setAttribute("hidden", "");
  form.hidden = false;
  liveRegion.textContent = "";

  // Return focus to first interactive element
  form.querySelector('input[type="checkbox"]').focus();
});

// Clear error state when user makes a selection
QUESTIONS.forEach(({ id }) => {
  const fieldset = document.getElementById(`fieldset-${id}`);
  const errorEl = document.getElementById(`error-${id}`);
  fieldset.addEventListener("change", () => {
    const checked = fieldset.querySelectorAll('input[type="checkbox"]:checked');
    if (checked.length > 0) clearError(fieldset, errorEl);
  });
});

function clearError(fieldset, errorEl) {
  fieldset.removeAttribute("aria-invalid");
  fieldset.removeAttribute("aria-describedby");
  errorEl.classList.remove("visible");
}
